SELECT SUM(spend_gbp) / NULLIF(SUM(attributed_first_observed_acquisitions), 0) AS media_only_cac_gbp, SUM(first_observed_acquisitions) AS first_observed_acquisitions, SUM(attributed_first_observed_acquisitions) AS attributed_first_observed_acquisitions, SUM(unattributed_first_observed_acquisitions) AS unattributed_first_observed_acquisitions FROM "fab_ent"."raw_marts"."mart_marketing__monthly_overview";
